package store

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"strings"

	"starline/learning-api/internal/domain/learning"
)

func directorySyncID(sourceID, nodeID, targetID string) string {
	sum := sha256.Sum256([]byte(sourceID + "\x00" + nodeID + "\x00" + targetID))
	return "dirsync-" + hex.EncodeToString(sum[:16])
}

// Full hierarchy identifies an existing branch; equal leaf names alone do not.
// IDs generated by a previous sync preserve identity on later rename/reorder.
func directoryPaths(nodes []learning.CurriculumNode) (map[string]string, error) {
	byID := map[string]learning.CurriculumNode{}
	for _, node := range nodes {
		byID[node.ID] = node
	}
	out := map[string]string{}
	seenPaths := map[string]bool{}
	for _, node := range nodes {
		parts := []string{}
		seen := map[string]bool{}
		for current := node; ; {
			if seen[current.ID] {
				return nil, errors.New("目录层级循环，不能同步")
			}
			seen[current.ID] = true
			part, _ := json.Marshal([]string{string(current.Type), curriculumNodePathLabel(current)})
			parts = append([]string{string(part)}, parts...)
			if current.ParentID == "" {
				break
			}
			parent, ok := byID[current.ParentID]
			if !ok {
				return nil, errors.New("目录缺少上级，不能同步")
			}
			current = parent
		}
		path := strings.Join(parts, "/")
		if seenPaths[path] {
			return nil, errors.New("目录存在相同完整路径，请先区分章节再同步")
		}
		seenPaths[path] = true
		out[node.ID] = path
	}
	return out, nil
}

func directoryLabels(nodes []learning.CurriculumNode) map[string]string {
	byID := map[string]learning.CurriculumNode{}
	for _, node := range nodes {
		byID[node.ID] = node
	}
	labels := map[string]string{}
	for _, node := range nodes {
		parts := []string{}
		for current := node; ; {
			parts = append([]string{curriculumNodePathLabel(current)}, parts...)
			if current.ParentID == "" {
				break
			}
			current = byID[current.ParentID]
		}
		labels[node.ID] = strings.Join(parts, " / ")
	}
	return labels
}

func findCourseIndex(courses []learning.Course, id string) int {
	for i, course := range courses {
		if course.ID == id {
			return i
		}
	}
	return -1
}

func (s *MemoryStore) remapDirectorySyncLinks(courseID string, mapping map[string]string) {
	for i, course := range s.courses {
		if len(course.DirectorySyncMap) == 0 {
			continue
		}
		links := map[string]string{}
		for key, value := range course.DirectorySyncMap {
			if strings.HasPrefix(key, courseID+":") {
				if next := mapping[strings.TrimPrefix(key, courseID+":")]; next != "" {
					key = courseID + ":" + next
				}
			}
			if course.ID == courseID {
				if next := mapping[value]; next != "" {
					value = next
				}
			}
			links[key] = value
		}
		s.courses[i].DirectorySyncMap = links
	}
}

func (s *MemoryStore) directorySyncSource(p learning.Principal, req learning.CourseDirectorySyncRequest) (learning.Course, error) {
	source, ok := s.findCourse(strings.TrimSpace(req.SourceCourseID))
	if !p.CanMaintainCourses() || !ok || !canSeeCourse(p, source) {
		return source, errors.New("源课程不存在或无权访问")
	}
	if len(source.Curriculum) == 0 {
		return source, errors.New("源课程尚无目录")
	}
	if source.Status != learning.StatusEnabled {
		return source, errors.New("源课程已停用，请先启用课程")
	}
	if len(req.TargetCourseIDs) > 100 {
		return source, errors.New("单次最多同步 100 门课程")
	}
	if len(req.TargetCourseIDs) == 0 {
		return source, errors.New("请选择目标课程")
	}
	if len(req.UnitIDs) > 0 {
		if _, err := directoryPaths(source.Curriculum); err != nil {
			return source, err
		}
		selected := map[string]bool{}
		for _, id := range req.UnitIDs {
			found := false
			for _, node := range source.Curriculum {
				if node.ID == id && node.Type == learning.CurriculumUnit && node.ParentID == "" {
					found = true
					break
				}
			}
			if !found {
				return source, errors.New("请选择有效的 Unit")
			}
			selected[id] = true
		}
		for changed := true; changed; {
			changed = false
			for _, node := range source.Curriculum {
				if !selected[node.ID] && selected[node.ParentID] {
					selected[node.ID] = true
					changed = true
				}
			}
		}
		nodes := []learning.CurriculumNode{}
		for _, node := range source.Curriculum {
			if selected[node.ID] {
				nodes = append(nodes, node)
			}
		}
		source.Curriculum = nodes
	}
	return source, nil
}

func (s *MemoryStore) PreviewCourseDirectorySync(p learning.Principal, req learning.CourseDirectorySyncRequest) (learning.CourseDirectorySyncResult, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	source, err := s.directorySyncSource(p, req)
	if err != nil {
		return learning.CourseDirectorySyncResult{}, err
	}
	out := learning.CourseDirectorySyncResult{Targets: []learning.CourseDirectorySyncTarget{}}
	seen := map[string]bool{}
	for _, rawID := range req.TargetCourseIDs {
		id := strings.TrimSpace(rawID)
		if seen[id] {
			continue
		}
		seen[id] = true
		preview, _ := s.directorySyncTarget(p, source, id, req)
		out.Targets = append(out.Targets, preview)
	}
	return out, nil
}

func (s *MemoryStore) SyncCourseDirectory(operator string, p learning.Principal, req learning.CourseDirectorySyncRequest) (learning.CourseDirectorySyncResult, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	return persistentMutation(s, func(work *MemoryStore) (learning.CourseDirectorySyncResult, error) {
		source, err := work.directorySyncSource(p, req)
		if err != nil {
			return learning.CourseDirectorySyncResult{}, err
		}
		out := learning.CourseDirectorySyncResult{Targets: []learning.CourseDirectorySyncTarget{}}
		seen := map[string]bool{}
		for _, rawID := range req.TargetCourseIDs {
			id := strings.TrimSpace(rawID)
			if seen[id] {
				continue
			}
			seen[id] = true
			preview, planned := work.directorySyncTarget(p, source, id, req)
			if preview.Error == "" && preview.Status == "" {
				unresolved := false
				for _, conflict := range preview.Conflicts {
					if !conflict.Resolved {
						unresolved = true
					}
				}
				if unresolved {
					preview.Error = "请先确认目录对应关系并重新预览"
				} else if req.Snapshots[id] == "" || req.Snapshots[id] != preview.Snapshot {
					// A completed, unchanged retry is safe; a new operation requires the exact preview.
					before, _ := json.Marshal(work.courses[findCourseIndex(work.courses, id)].DirectorySyncMap)
					after, _ := json.Marshal(planned.courses[findCourseIndex(planned.courses, id)].DirectorySyncMap)
					if req.Snapshots[id] != "" && len(preview.Added)+len(preview.Updated)+len(preview.Merged)+len(preview.MaterialsAdded)+len(preview.MaterialsUpdated) == 0 && string(before) == string(after) {
						preview.Status = "已同步"
					} else {
						preview.Error = "目录或讲义已发生变化，请重新预览"
					}
				} else {
					work.publishMutation(planned)
					detail, _ := json.Marshal(preview)
					work.prependLogDetail(operator, "同步课程目录及讲义", source.Name+" → "+preview.CourseName, string(detail))
					preview.Status = "已同步"
				}
			}
			if preview.Error != "" {
				preview.Status = "失败"
			}
			out.Targets = append(out.Targets, preview)
		}
		return out, nil
	})
}
